-- ============================================================
-- Marketing consent per client and channel (dbo.clientContactPreferences).
-- Table: sql/migration_history/migrations/2026-10-30_client_contact_preferences.sql
--
-- Generated by posgmo-factory, corrected by hand (see the migration header):
-- action 1 is a real upsert on (companyId, clientId, channel), every read and
-- write is scoped to companyId, and every exit returns
-- {"result":[{"value","msg","error"}]} as ONE JSON cell (execute_sp_json).
--
-- sp_clientContactPreferences  @pjsonfile = {"clientContactPreferences":[{...}]}
--   1|2 upsert     companyId, clientId, channel, marketingOptIn, source, updatedByUserId?
--   3   delete     companyId, clientId, channel
--   4   keyword    companyId, phone, marketingOptIn — WhatsApp BAJA/ALTA. Applies to
--                  every active client of the company with that cellphone (last 10
--                  digits, same match as sp_whatsappCustomerRewards, walk-in
--                  "Desconocido" excluded). value = clients updated (0 = no match).
-- optedInAt / optedOutAt (UTC) move only when the state actually changes, so
-- they record when the client consented or withdrew, not the last repeat.
-- ============================================================
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

CREATE OR ALTER PROCEDURE [dbo].[sp_clientContactPreferences]
    @pjsonfile NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @value NVARCHAR(50) = N'', @msg NVARCHAR(4000) = N'', @error NVARCHAR(10) = N'';

    BEGIN TRY
        DECLARE @action    INT           = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].action'));
        DECLARE @companyId INT           = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].companyId'));
        DECLARE @clientId  INT           = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].clientId'));
        DECLARE @channel   NVARCHAR(20)  = LOWER(JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].channel'));
        DECLARE @optIn     BIT           = TRY_CONVERT(BIT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].marketingOptIn'));
        DECLARE @source    NVARCHAR(30)  = JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].source');
        DECLARE @userId    INT           = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].updatedByUserId'));
        DECLARE @phone     NVARCHAR(30)  = JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].phone');
        DECLARE @now       DATETIME      = GETUTCDATE();

        IF @companyId IS NULL
        BEGIN
            SELECT @error = N'1', @msg = N'companyId is required';
            GOTO Finish;
        END

        DECLARE @targets TABLE (clientId INT PRIMARY KEY);

        IF @action IN (1, 2)
        BEGIN
            IF @clientId IS NULL OR @channel IS NULL OR @optIn IS NULL OR @source IS NULL
            BEGIN
                SELECT @error = N'1', @msg = N'clientId, channel, marketingOptIn and source are required';
                GOTO Finish;
            END
            IF @channel NOT IN (N'whatsapp', N'sms', N'push')
               OR @source NOT IN (N'pos_checkout', N'client_app', N'whatsapp_keyword', N'admin')
            BEGIN
                SELECT @error = N'1', @msg = N'invalid channel or source';
                GOTO Finish;
            END
            -- the client must belong to the caller's company
            INSERT INTO @targets (clientId)
            SELECT c.clientId FROM [dbo].[clients] c
            WHERE c.clientId = @clientId AND c.companyId = @companyId;
            IF NOT EXISTS (SELECT 1 FROM @targets)
            BEGIN
                SELECT @error = N'1', @msg = N'client not found in this company';
                GOTO Finish;
            END
        END
        ELSE IF @action = 4
        BEGIN
            DECLARE @digits NVARCHAR(30) = RIGHT(REPLACE(REPLACE(REPLACE(ISNULL(@phone, N''), N'+', N''), N' ', N''), N'-', N''), 10);
            IF LEN(@digits) < 10 OR @optIn IS NULL
            BEGIN
                SELECT @error = N'1', @msg = N'phone and marketingOptIn are required';
                GOTO Finish;
            END
            SELECT @channel = N'whatsapp', @source = N'whatsapp_keyword', @userId = NULL;
            INSERT INTO @targets (clientId)
            SELECT c.clientId FROM [dbo].[clients] c
            WHERE c.companyId = @companyId
              AND c.isActive = 1
              AND c.first_name <> N'Desconocido'
              AND RIGHT(REPLACE(REPLACE(REPLACE(c.cellphone, N'+', N''), N' ', N''), N'-', N''), 10) = @digits;
        END
        ELSE IF @action = 3
        BEGIN
            DELETE FROM [dbo].[clientContactPreferences]
            WHERE companyId = @companyId AND clientId = @clientId AND channel = @channel;
            SELECT @value = CAST(@@ROWCOUNT AS NVARCHAR(50)), @msg = N'Deleted Successfully';
            GOTO Finish;
        END
        ELSE
        BEGIN
            SELECT @error = N'1', @msg = N'Invalid action';
            GOTO Finish;
        END

        BEGIN TRANSACTION;

        UPDATE t
        SET t.optedInAt       = CASE WHEN @optIn = 1 AND t.marketingOptIn = 0 THEN @now ELSE t.optedInAt END,
            t.optedOutAt      = CASE WHEN @optIn = 0 AND t.marketingOptIn = 1 THEN @now ELSE t.optedOutAt END,
            t.marketingOptIn  = @optIn,
            t.source          = @source,
            t.updatedByUserId = @userId,
            t.active          = 1,
            t.updated_at      = GETDATE()
        FROM [dbo].[clientContactPreferences] t WITH (UPDLOCK, SERIALIZABLE)
        INNER JOIN @targets x ON x.clientId = t.clientId
        WHERE t.companyId = @companyId AND t.channel = @channel;

        INSERT INTO [dbo].[clientContactPreferences]
            (companyId, clientId, channel, marketingOptIn, source, optedInAt, optedOutAt, updatedByUserId, active, created_At)
        SELECT @companyId, x.clientId, @channel, @optIn, @source,
               CASE WHEN @optIn = 1 THEN @now END,
               CASE WHEN @optIn = 0 THEN @now END,
               @userId, 1, GETDATE()
        FROM @targets x
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[clientContactPreferences] t
                          WHERE t.companyId = @companyId AND t.clientId = x.clientId AND t.channel = @channel);

        COMMIT TRANSACTION;

        SELECT @value = CASE WHEN @action = 4 THEN CAST((SELECT COUNT(*) FROM @targets) AS NVARCHAR(50))
                             ELSE CAST(@clientId AS NVARCHAR(50)) END,
               @msg   = N'Saved Successfully';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        SELECT @error = N'1', @msg = ERROR_MESSAGE();
    END CATCH

Finish:
    SELECT (SELECT @value AS value, @msg AS msg, @error AS error
            FOR JSON PATH, ROOT('result'), INCLUDE_NULL_VALUES) AS jsonResult;
END
GO

-- ── all preferences of the company; optional clientId narrows to one client ──
CREATE OR ALTER PROCEDURE [dbo].[sp_clientContactPreferences_all]
    @pjsonfile NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @companyId INT = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].companyId'));
    DECLARE @clientId  INT = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].clientId'));

    SELECT
        clientContactPreferenceId, companyId, clientId, channel, marketingOptIn, source,
        ISNULL(CONVERT(VARCHAR(30), optedInAt, 126), '')  AS optedInAt,
        ISNULL(CONVERT(VARCHAR(30), optedOutAt, 126), '') AS optedOutAt,
        ISNULL(updatedByUserId, 0) AS updatedByUserId,
        active,
        CONVERT(VARCHAR(30), created_At, 126) AS created_At,
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM [dbo].[clientContactPreferences]
    WHERE companyId = @companyId
      AND (@clientId IS NULL OR clientId = @clientId)
    ORDER BY clientId, channel
    FOR JSON PATH, ROOT('clientContactPreferences');
END
GO

-- ── one row by id, only inside the caller's company ──
CREATE OR ALTER PROCEDURE [dbo].[sp_clientContactPreferences_one]
    @pjsonfile NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @companyId INT = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].companyId'));
    DECLARE @id        INT = TRY_CONVERT(INT, JSON_VALUE(@pjsonfile, '$.clientContactPreferences[0].clientContactPreferenceId'));

    SELECT
        clientContactPreferenceId, companyId, clientId, channel, marketingOptIn, source,
        ISNULL(CONVERT(VARCHAR(30), optedInAt, 126), '')  AS optedInAt,
        ISNULL(CONVERT(VARCHAR(30), optedOutAt, 126), '') AS optedOutAt,
        ISNULL(updatedByUserId, 0) AS updatedByUserId,
        active,
        CONVERT(VARCHAR(30), created_At, 126) AS created_At,
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM [dbo].[clientContactPreferences]
    WHERE clientContactPreferenceId = @id AND companyId = @companyId
    FOR JSON PATH, ROOT('clientContactPreferences');
END
GO
